DetectDoubleBottom:
bool DetectDoubleBottom(PatternSignal &signal)
  {
   signal.valid = false;
   signal.buySignal = false;
   signal.sellSignal = false;
   signal.type = PATTERN_NONE;

   int s1,s2,s3;

   double p1,p2,p3;

   if(!GetRecentSwingLows(PERIOD_M1,
                          SwingDepth,
                          PatternLookbackBars,
                          s1,p1,
                          s2,p2,
                          s3,p3))
      return false;

   // 最新側の安値
   double recentLow = p1;

   // 1つ前の安値
   double previousLow = p2;

   double atr = GetATR(PERIOD_M1,14,1);

   if(atr <= 0)
      return false;

   // 2つの安値の差
   double difference = MathAbs(recentLow-previousLow);

   if(difference > atr*PatternToleranceATR)
      return false;

   // 安値間の最高値＝ネックライン
   int startShift = MathMin(s1,s2);

   int endShift = MathMax(s1,s2);

   double neckline = 0.0;

   for(int shift=endShift;
       shift>=startShift;
       shift--)
     {
      double high = iHigh(_Symbol,PERIOD_M1,shift);

      if(high > neckline)
         neckline = high;
     }

   if(neckline <= 0)
      return false;

   // 現在の確定足
   double close1 = iClose(_Symbol,PERIOD_M1,1);

   // ネックライン突破
   double close2=iClose(_Symbol,PERIOD_M1,2);
   double level=neckline+atr*NecklineToleranceATR;
   bool breakout = (close2>0 && close2<=level && close1>level);

   if(!breakout)
      return false;

   signal.type = PATTERN_DOUBLE_BOTTOM;

   signal.valid = true;

   signal.buySignal = true;

   signal.sellSignal = false;

   signal.firstPoint = previousLow;

   signal.secondPoint = recentLow;

   signal.headPoint = 0;

   signal.neckline = neckline;

   signal.entryLevel = close1;

   signal.patternStrength = 70.0;

   signal.firstTime =
      iTime(_Symbol,PERIOD_M1,s2);

   signal.secondTime =
      iTime(_Symbol,PERIOD_M1,s1);

   signal.necklineTime =
      iTime(_Symbol,PERIOD_M1,startShift);

   return true;
  }

DetectDoubleTop:
bool DetectDoubleTop(PatternSignal &signal)
  {
   signal.valid = false;
   signal.buySignal = false;
   signal.sellSignal = false;
   signal.type = PATTERN_NONE;

   int s1,s2,s3;

   double p1,p2,p3;

   if(!GetRecentSwingHighs(PERIOD_M1,
                           SwingDepth,
                           PatternLookbackBars,
                           s1,p1,
                           s2,p2,
                           s3,p3))
      return false;

   double recentHigh = p1;

   double previousHigh = p2;

   double atr = GetATR(PERIOD_M1,14,1);

   if(atr <= 0)
      return false;

   double difference =
      MathAbs(recentHigh-previousHigh);

   if(difference > atr*PatternToleranceATR)
      return false;

   int startShift = MathMin(s1,s2);

   int endShift = MathMax(s1,s2);

   double neckline = DBL_MAX;

   for(int shift=endShift;
       shift>=startShift;
       shift--)
     {
      double low = iLow(_Symbol,PERIOD_M1,shift);

      if(low < neckline)
         neckline = low;
     }

   if(neckline <= 0 || neckline == DBL_MAX)
      return false;

   double close1 = iClose(_Symbol,PERIOD_M1,1);

   double close2=iClose(_Symbol,PERIOD_M1,2);
   double level=neckline-atr*NecklineToleranceATR;
   bool breakout = (close2>0 && close2>=level && close1<level);

   if(!breakout)
      return false;

   signal.type = PATTERN_DOUBLE_TOP;

   signal.valid = true;

   signal.buySignal = false;

   signal.sellSignal = true;

   signal.firstPoint = previousHigh;

   signal.secondPoint = recentHigh;

   signal.headPoint = 0;

   signal.neckline = neckline;

   signal.entryLevel = close1;

   signal.patternStrength = 70.0;

   signal.firstTime =
      iTime(_Symbol,PERIOD_M1,s2);

   signal.secondTime =
      iTime(_Symbol,PERIOD_M1,s1);

   signal.necklineTime =
      iTime(_Symbol,PERIOD_M1,startShift);

   return true;
  }

DetectInverseHeadShoulders:
bool DetectInverseHeadShoulders(PatternSignal &signal)
  {
   signal.valid = false;
   signal.buySignal = false;
   signal.sellSignal = false;
   signal.type = PATTERN_NONE;

   int s1,s2,s3;

   double p1,p2,p3;

   if(!GetRecentSwingLows(PERIOD_M1,
                          SwingDepth,
                          PatternLookbackBars,
                          s1,p1,
                          s2,p2,
                          s3,p3))
      return false;

   if(s3<0 || p3<=0) return false;

   // 3つの安値
   if(s3<0 || p3<=0) return false;

   // p3 = 左肩
   // p2 = ヘッド
   // p1 = 右肩

   double leftShoulder  = p3;

   double head          = p2;

   double rightShoulder = p1;

   double atr = GetATR(PERIOD_M1,14,1);

   if(atr <= 0)
      return false;

   // ヘッドが左右の肩より明確に低い
   if(head >= leftShoulder-atr*0.20)
      return false;

   if(head >= rightShoulder-atr*0.20)
      return false;

   // 左右の肩の高さが近い
   double shoulderDiff =
      MathAbs(leftShoulder-rightShoulder);

   if(shoulderDiff > atr*PatternToleranceATR*2.0)
      return false;

   // ネックライン
   int leftShift  = s3;

   int rightShift = s1;

   int startShift = MathMin(leftShift,rightShift);

   int endShift = MathMax(leftShift,rightShift);

   double neckline = 0.0;

   for(int shift=endShift;
       shift>=startShift;
       shift--)
     {
      double high = iHigh(_Symbol,PERIOD_M1,shift);

      if(high > neckline)
         neckline = high;
     }

   if(neckline <= 0)
      return false;

   double close1 = iClose(_Symbol,PERIOD_M1,1);

   double close2=iClose(_Symbol,PERIOD_M1,2);
   double level=neckline+atr*NecklineToleranceATR;
   bool breakout = (close2>0 && close2<=level && close1>level);

   if(!breakout)
      return false;

   signal.type =
      PATTERN_INVERSE_HEAD_SHOULDERS;

   signal.valid = true;

   signal.buySignal = true;

   signal.sellSignal = false;

   signal.firstPoint = leftShoulder;

   signal.secondPoint = rightShoulder;

   signal.headPoint = head;

   signal.neckline = neckline;

   signal.entryLevel = close1;

   signal.patternStrength = 85.0;

   signal.firstTime =
      iTime(_Symbol,PERIOD_M1,s3);

   signal.headTime =
      iTime(_Symbol,PERIOD_M1,s2);

   signal.secondTime =
      iTime(_Symbol,PERIOD_M1,s1);

   return true;
  }

